ROADMAPS={"Software Engineer":[("Foundations","Review programming, data structures and algorithms"),("Web development","Build responsive HTML, CSS and JavaScript interfaces"),("Frameworks","Build a React application and consume REST APIs"),("Backend and databases","Create an API and design SQL tables"),("Engineering practices","Use Git, tests, Docker and deployment"),("Portfolio and interviews","Publish two projects and practise technical interviews")],"Data Analyst":[("SQL and spreadsheets","Practise joins, aggregations, Excel and data cleaning"),("Python analytics","Learn Python, Pandas and NumPy"),("Visualization","Create dashboards with Power BI or Tableau"),("Statistics","Practise descriptive statistics and basic inference"),("Portfolio","Complete two end-to-end analysis projects"),("Job readiness","Explain insights and practise interview cases")],"Data Scientist":[("Python foundations","Practise Python, NumPy and Pandas"),("Statistics","Study probability, inference and regression"),("Machine learning","Train and evaluate baseline models"),("Data pipelines","Clean data and build repeatable workflows"),("Projects","Publish two reproducible ML projects"),("Interview readiness","Review metrics, modelling trade-offs and case studies")],"Full Stack Developer":[("Web foundations","HTML, CSS, JavaScript and accessibility"),("Frontend","Build a React app with routing and forms"),("Backend","Implement REST endpoints and validation"),("Data layer","Model relational data and authentication"),("Testing and deployment","Add tests, environment config and deployment"),("Portfolio","Ship a documented full-stack application")],"Cloud Engineer":[("Linux and networking","Practise shell, DNS, HTTP and networking basics"),("Cloud fundamentals","Learn core AWS or Azure services"),("Containers","Build Docker images and deploy a service"),("Infrastructure","Practise IAM, monitoring and infrastructure as code"),("Reliability","Add logs, alerts, backups and security checks"),("Portfolio","Deploy and document a cloud project")],"UI/UX Designer":[("Design foundations","Study visual hierarchy, typography and accessibility"),("Research","Write interview questions and synthesise findings"),("Wireframes","Create user flows and low-fidelity wireframes"),("Prototyping","Build interactive Figma prototypes"),("Usability","Run usability tests and iterate"),("Portfolio","Document three case studies and decisions")] }
def create_roadmap(career):
    steps=ROADMAPS.get(career)
    if not steps: raise ValueError('Unsupported career. Choose a listed career.')
    return {"career":career,"duration_weeks":12,"steps":[{"week":i*2+1,"title":title,"task":task,"status":"not_started"} for i,(title,task) in enumerate(steps)]}
